                                  "filename": "write-ahead-logging-wal-ketahanan-data-durability-pada-indeks-vektor.py",
                                  "code": "import json\nimport os\nimport tempfile\n\n# Simulasi Engine WAL Miniatur: Pencatatan Log dan Pemulihan Indeks Pasca-Crash\nclass MiniWALVectorDB:\n    def __init__(self, wal_path: str):\n        self.wal_path = wal_path\n        self.in_memory_index = {} # Simulasi indeks memori aktif\n        \n    def insert(self, vec_id: int, vector: list):\n        # 1. TULIS LOG WAL TERLEBIH DAHULU KE DISK (Append-Only)\n        log_entry = {\"op\": \"INSERT\", \"id\": vec_id, \"vector\": vector}\n        with open(self.wal_path, \"a\", encoding=\"utf-8\") as f:\n            f.write(json.dumps(log_entry) + \"\\n\")\n            f.flush()\n            os.fsync(f.fileno()) # Paksa sinkronisasi ke blok disk fisik\n            \n        # 2. Perbarui indeks memori aktif\n        self.in_memory_index[vec_id] = vector\n        \n    def simulate_crash(self):\n        # Simulasi crash: seluruh struktur memori RAM terhapus seketika!\n        self.in_memory_index.clear()\n        \n    def recover_from_wal(self):\n        # Pemulihan status: replay transaksi dari berkas WAL fisik\n        replayed_ops = 0\n        if os.path.exists(self.wal_path):\n            with open(self.wal_path, \"r\", encoding=\"utf-8\") as f:\n                for line in f:\n                    if line.strip():\n                        entry = json.loads(line)\n                        if entry[\"op\"] == \"INSERT\":\n                            self.in_memory_index[entry[\"id\"]] = entry[\"vector\"]\n                            replayed_ops += 1\n        return replayed_ops\n\nwith tempfile.NamedTemporaryFile(delete=False) as tmp_f:\n    wal_file = tmp_f.name\n\ntry:\n    db = MiniWALVectorDB(wal_file)\n    db.insert(101, [0.12, 0.45, 0.88])\n    db.insert(102, [0.91, 0.22, 0.05])\n    print(f\"Status Memori Sebelum Crash: {len(db.in_memory_index)} vektor aktif\")\n    \n    db.simulate_crash()\n    print(f\"Status Memori Saat Crash Terjadi: {len(db.in_memory_index)} vektor (RAM Bersih!)\")\n    \n    n_rec = db.recover_from_wal()\n    print(f\"Proses Recovery Berhasil: {n_rec} operasi log WAL di-replay ulang\")\n    print(f\"Status Memori Setelah Recovery: {len(db.in_memory_index)} vektor pulih sempurna\")\nfinally:\n    if os.path.exists(wal_file):\n        os.remove(wal_file)",
